namespace MiniFazendinha.EditorTools {public static class FarmV38Review {[UnityEditor.MenuItem("MiniFazendinha/V3.8/Review collection panels")]public static void Review(){
var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var ui=UnityEngine.Object.FindAnyObjectByType<MiniFazendinha.Animals.FarmAnimalContextUI>().Management;
var well=UnityEngine.Object.FindAnyObjectByType<MiniFazendinha.Animals.WaterWellController>();
var stock=UnityEngine.Object.FindAnyObjectByType<MiniFazendinha.Planting.FarmInventory>();
var log=new System.Text.StringBuilder();
System.Action<bool,string> check=(ok,label)=>{log.AppendLine((ok?"PASS ":"FAIL ")+label);System.IO.File.WriteAllText("Reports/V38/collection-ui.txt",log.ToString());if(!ok)throw new System.Exception(label);};
ui.ShowWell(well,UnityEngine.Vector2.zero);UnityEngine.Canvas.ForceUpdateCanvases();
var size=ui.Panel.sizeDelta;check(size==new UnityEngine.Vector2(300,206),"Well popup is compact 300x206");
UnityEngine.UI.Button collect=null;foreach(var b in ui.Panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.name=="Coletar água")collect=b;
var rect=(UnityEngine.RectTransform)collect.transform;check(UnityEngine.Mathf.Abs(rect.anchoredPosition.x+rect.rect.width*.5f-ui.Panel.rect.width*.5f)<.1f,"Well collection button horizontally centered");check(collect.GetComponentInChildren<TMPro.TMP_Text>().text=="Coletar","Well uses textual label");
foreach(var resolution in new[]{new UnityEngine.Vector2Int(1920,1080),new UnityEngine.Vector2Int(1600,900),new UnityEngine.Vector2Int(1366,768)})MiniFazendinha.EditorTools.FarmContextUXReview.Capture("V38-well-"+resolution.x+"x"+resolution.y,resolution.x,resolution.y);
int initial=stock.Quantity(well.WaterItem),amount=well.Available;check(amount>0,"Well water available for collection test");collect.onClick.Invoke();ui.Tick();check(stock.Quantity(well.WaterItem)==initial+amount&&well.Available==0,"Well transfer exact and recharge active");collect.onClick.Invoke();check(stock.Quantity(well.WaterItem)==initial+amount,"Repeated well click cannot duplicate");
var tree=UnityEngine.Object.FindAnyObjectByType<MiniFazendinha.FruitTrees.FruitTree>();check(tree!=null,"Actual planted fruit tree exists");typeof(MiniFazendinha.FruitTrees.FruitTree).GetMethod("Advance",flags).Invoke(tree,new object[]{tree.Definition.GrowthSeconds+tree.Definition.ProductionSeconds});ui.ShowTree(tree,UnityEngine.Vector2.zero);check(ui.Panel.sizeDelta==size,"Tree popup shares well dimensions");
collect=null;foreach(var b in ui.Panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.name=="Colher frutas")collect=b;rect=(UnityEngine.RectTransform)collect.transform;check(UnityEngine.Mathf.Abs(rect.anchoredPosition.x+rect.rect.width*.5f-ui.Panel.rect.width*.5f)<.1f,"Tree button centered");check(collect.GetComponentInChildren<TMPro.TMP_Text>().text=="Coletar","Tree collection label textual");
foreach(var resolution in new[]{new UnityEngine.Vector2Int(1920,1080),new UnityEngine.Vector2Int(1600,900),new UnityEngine.Vector2Int(1366,768)})MiniFazendinha.EditorTools.FarmContextUXReview.Capture("V38-tree-"+resolution.x+"x"+resolution.y,resolution.x,resolution.y);
initial=stock.Quantity(tree.Definition.Fruit);amount=tree.AvailableFruit;collect.onClick.Invoke();check(stock.Quantity(tree.Definition.Fruit)==initial+amount&&tree!=null&&tree.AvailableFruit==0,"Tree collection exact and tree preserved");collect.onClick.Invoke();check(stock.Quantity(tree.Definition.Fruit)==initial+amount,"Repeated tree click cannot duplicate");
foreach(var a in MiniFazendinha.Animals.FarmAnimalRegistry.All){ui.ShowAnimal(a);UnityEngine.UI.Button button=null;foreach(var b in ui.Panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.name=="Coletar produção")button=b;check(button.GetComponentInChildren<TMPro.TMP_Text>().text=="Coleta",a.Definition.name+" individual collection is textual");ui.ShowShelter(a.Home);foreach(var b in ui.Panel.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.name=="Coletar "+a.Definition.Product.DisplayName)check(b.GetComponentInChildren<TMPro.TMP_Text>().text=="Coleta",a.Definition.name+" pen collection is textual");if(a.Definition.name=="Pig"){check(a.Definition.Product.Identifier=="bacon"&&a.Definition.Product.DisplayName=="Bacon"&&a.Definition.Product.Icon!=null,"Pig uses bacon item and icon");MiniFazendinha.EditorTools.FarmContextUXReview.Capture("V38-pigs",1600,900);}}
ui.Close();log.AppendLine("COMPLETED");System.IO.File.WriteAllText("Reports/V38/collection-ui.txt",log.ToString());

}}}